## Submitted testbench
```systemverilog
module tb;
  // -------------------------------------------------------------
  // Clock, reset and global signals
  // -------------------------------------------------------------
  logic clk = 0;
  logic rst = 0;
  logic [15:0] prescale = 16'd1;   // non‑zero prescale for bit timing
  logic rxd = 1'b1;                // UART receive line (open‑drain style)

  // -------------------------------------------------------------
  // DUT interface signals
  // -------------------------------------------------------------
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready = 1'b1; // always ready for AXI output
  logic       busy;
  logic       overrun_error;
  logic       frame_error;

  // -------------------------------------------------------------
  // Instantiate the UART_Rx module (no modifications allowed)
  // -------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale)
  );

  // -------------------------------------------------------------
  // Clock generation (125 MHz)
  // -------------------------------------------------------------
  always #4 clk = ~clk;  // 8 ns period

  // -------------------------------------------------------------
  // Helper task: wait a given number of negedge clock cycles
  // -------------------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  // -------------------------------------------------------------
  // Task: send one UART frame (start + 8 data bits + stop) with an
  //       optional glitch in a chosen data‑bit position.
  //       The glitch consists of toggling the line and toggling back
  //       while the bit period is held (prescale = 1 → 8 cycles per bit).
  // -------------------------------------------------------------
  task automatic send_frame(input [7:0] data_byte, input int glitch_bit_index);
    // ---- start bit (0) -------------------------------------------------
    rxd <= 0;
    repeat (8) @(negedge clk); // 8 cycles = 1 * prescale * 8

    // ---- data bits ----------------------------------------------------
    for (int i = 0; i < 8; i++) begin
      logic b = data_byte[i];
      if (i == glitch_bit_index) begin
        // hold expected level for 3 cycles
        repeat (3) @(negedge clk);
        // toggle opposite for 1 cycle
        rxd <= ~b; wait_clks(1);
        // toggle back to expected level
        rxd <= b;
        // remaining cycles to complete the 8‑cycle bit period
        repeat (4) @(negedge clk);
      end else begin
        rxd <= b;
        repeat (8) @(negedge clk);
      end
    end

    // ---- stop bit (1) -------------------------------------------------
    rxd <= 1;
    repeat (8) @(negedge clk);
  endtask

  // -------------------------------------------------------------
  // Rising‑edge detector for m_axis_tvalid
  // -------------------------------------------------------------
  logic prev_m_axis_tvalid = 0;
  logic [7:0] captured_data;
  logic first_data_captured = 0;

  always @(posedge clk) begin
    prev_m_axis_tvalid <= m_axis_tvalid;
    if (m_axis_tvalid && !prev_m_axis_tvalid) begin
      captured_data <= m_axis_tdata;

      // ---------------------------------------------------------
      // First valid frame must deliver 0xA5
      // ---------------------------------------------------------
      if (!first_data_captured) begin
        if (captured_data !== 8'hA5) $fatal(1, "First byte is not 0xA5 (got %02h)", captured_data);
        first_data_captured <= 1;
      end
      // ---------------------------------------------------------
      // Second valid frame should deliver 0x5A with no errors
      // ---------------------------------------------------------
      else begin
        if (captured_data === 8'h5A && !frame_error && !overrun_error) begin
          // Let the coverage mechanism record the hit, then finish
          repeat (2) @(posedge clk);
          $finish;
        end
        else begin
          $fatal(1, "Second byte not 0x5A or errors present (data=%02h, frame_error=%b, overrun=%b)",
                 captured_data, frame_error, overrun_error);
        end
      end
    end
  end

  // -------------------------------------------------------------
  // Timeout watchdog
  // -------------------------------------------------------------
  initial begin
    #100ms;
    $fatal(1, "Timeout waiting for coverage hit");
  end

  // -------------------------------------------------------------
  // Main stimulus process
  // -------------------------------------------------------------
  initial begin
    // ----- reset ----------------------------------------------------
    rxd <= 1'b1;
    wait_clks(2);
    rst <= 1'b1;
    wait_clks(2);
    rst <= 1'b0;
    wait_clks(2);

    // ----- first frame: 0xA5 with glitch on bit 2 (third data bit) ---
    send_frame(8'hA5, 2);                     // glitch inside 3rd data bit
    // wait until receiver is idle (busy low) before next frame
    while (busy) wait_clks(1);

    // ----- second frame: 0x5A with glitch on same bit ---------------
    send_frame(8'h5A, 2);                       // glitch inside 3rd data bit

    // The monitor in the always block will detect the second rising edge
    // and invoke $finish, satisfying the coverage requirement.
  end
endmodule
